class ZScoreMomentum(Strategy):
    name = "zscore_momentum"
    LOOKBACK = 30
    THRESHOLD = 1.5
    warmup_bars = 35

    def on_bar(self, symbol, store):
        window = store.window(symbol, self.timeframe)
        if len(window) < self.warmup_bars:
            return math.nan
        closes = window.closes()
        if len(closes) < 2:
            return math.nan
        rets = np.diff(np.log(closes))
        z = ta.zscore(rets, self.LOOKBACK)
        if not math.isfinite(z):
            return math.nan
        if z > self.THRESHOLD:
            return 1.0
        if z < -self.THRESHOLD:
            return -1.0
        return 0.0
